<template>
  <div class="space-y-6">
    <PageHeader title="系统总览" description="查看真实节点状态、已采样账户流量、域名记录和配置发布结果。"><template #actions><button :disabled="loading" @click="load" class="ios-btn-secondary disabled:opacity-40">{{ loading ? '刷新中…' : '刷新' }}</button></template></PageHeader>
    <ErrorState v-if="error" :message="error" @retry="load" /><LoadingSkeleton v-else-if="!dashboard" />
    <template v-if="dashboard">
      <p class="text-xs text-gray-500">今日按 {{ dashboard.timezone }} 计算，自 {{ formatTime(dashboard.dayStart) }} 起；最近更新 {{ formatTime(dashboard.generatedAt) }}。账户计数不分摊到域名。</p>
      <div class="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <div class="panel-card p-5"><p class="text-xs text-gray-500">在线节点</p><p class="text-2xl font-semibold mt-3">{{ dashboard.counts.onlineNodes }}<span class="text-sm text-gray-400"> / {{ dashboard.counts.totalNodes }}</span></p></div>
        <div class="panel-card p-5"><p class="text-xs text-gray-500">异常节点</p><p class="text-2xl font-semibold mt-3">{{ dashboard.counts.abnormalNodes }}</p><p class="text-xs text-gray-500 mt-2">{{ dashboard.counts.offlineNodes }} 个离线</p></div>
        <div class="panel-card p-5"><p class="text-xs text-gray-500">在线用户</p><p class="text-xl font-semibold mt-3">{{ dashboard.counts.onlineUsers ?? '尚未测量' }}</p></div>
        <div class="panel-card p-5"><p class="text-xs text-gray-500">在线设备</p><p class="text-xl font-semibold mt-3">{{ dashboard.counts.onlineDevices ?? '尚未测量' }}</p></div>
        <div class="panel-card p-5"><p class="text-xs text-gray-500">当前连接数</p><p class="text-xl font-semibold mt-3">{{ dashboard.counts.activeConnections ?? '尚未测量' }}</p></div>
        <div class="panel-card p-5"><p class="text-xs text-gray-500">今日已采样上传</p><div class="text-xl mt-3"><TrafficValue v-if="dashboard.counts.trafficObservations" :bytes="dashboard.counts.todayUpload" /><span v-else>暂无样本</span></div></div>
        <div class="panel-card p-5"><p class="text-xs text-gray-500">今日已采样下载</p><div class="text-xl mt-3"><TrafficValue v-if="dashboard.counts.trafficObservations" :bytes="dashboard.counts.todayDownload" /><span v-else>暂无样本</span></div></div>
        <div class="panel-card p-5"><p class="text-xs text-gray-500">今日已上报阻断次数</p><p class="text-2xl font-semibold mt-3">{{ dashboard.counts.todayBlocked }}</p></div>
      </div>
      <p class="text-xs text-gray-500">连接统计覆盖 {{ dashboard.counts.measuredNodes }} / {{ dashboard.counts.expectedNodes }} 个启用节点。Xray 节点上报该用户的去重客户端 IP 数（回环地址排除），sing-box 节点不提供每用户在线数、显示未知；超限只告警，不切断连接。<template v-if="dashboard.counts.measuredNodes < dashboard.counts.expectedNodes">当前已测得 {{ dashboard.counts.measuredUsers }} 位用户、{{ dashboard.counts.measuredDevices }} 台设备、{{ dashboard.counts.measuredConnections }} 个连接；全量数据等待其余节点上报。</template></p>
      <section class="panel-card p-6 space-y-4"><div class="flex justify-between"><h2 class="font-semibold">节点状态</h2><router-link to="/nodes" class="text-sm text-blue-600">全部节点</router-link></div><EmptyState v-if="!dashboard.nodes.length" title="尚无节点" description="Owner 可以在节点列表生成一次性注册码。" />
        <div v-for="node in dashboard.nodes" :key="node.id" class="grid sm:grid-cols-4 gap-3 border-b border-gray-100 pb-4 text-sm"><div><router-link :to="'/nodes/'+node.id" class="font-semibold text-blue-600">{{ node.name }}</router-link><p class="text-xs text-gray-500 mt-1">{{ node.publicIp || node.hostname || '尚无地址' }}</p></div><StatusBadge :status="node.status" /><div class="text-xs text-gray-500">CPU {{ node.heartbeat.cpu_percent === undefined ? '未知' : node.heartbeat.cpu_percent.toFixed(1)+'%' }} · 内存 {{ node.heartbeat.memory_percent === undefined ? '未知' : node.heartbeat.memory_percent.toFixed(1)+'%' }}</div><p class="text-xs text-gray-500">{{ node.lastHeartbeat ? formatTime(node.lastHeartbeat) : '尚无心跳' }}</p></div>
      </section>
      <section class="panel-card p-6"><h2 class="font-semibold mb-4">今日账户流量趋势</h2><p v-if="!dashboard.trend.length" class="text-sm text-gray-500">暂无已采样账户流量。</p><div v-else class="space-y-3"><div v-for="hour in dashboard.trend" :key="hour.time" class="grid grid-cols-[9rem_1fr] gap-3 items-center text-xs"><span>{{ formatTime(hour.time) }}</span><div><div class="h-3 rounded bg-blue-100 overflow-hidden"><div class="h-full bg-blue-500" :style="{width:barWidth(hour)}"></div></div><p class="mt-1 text-gray-500"><TrafficValue :bytes="hour.upload" /> 上传 · <TrafficValue :bytes="hour.download" /> 下载</p></div></div></div><p class="text-xs text-gray-500 mt-4">按采样时间汇总小时差额，不是瞬时带宽或数据包时间。</p></section>
      <template v-if="isOwner">
        <div class="grid lg:grid-cols-2 gap-6"><section class="panel-card p-6"><h2 class="font-semibold mb-4">最近访问目标</h2><EmptyState v-if="!dashboard.recentAccess?.length" title="暂无访问记录" description="节点采集并上报后显示。" /><div v-for="(item,index) in dashboard.recentAccess" :key="index" class="border-b border-gray-100 py-3 text-sm"><p class="font-mono break-all">{{ item.domain || item.targetIp }}</p><p class="text-xs text-gray-500 mt-1">{{ item.userName || '身份未知' }} · {{ item.deviceName || '设备未知' }} · {{ item.nodeName }} · {{ item.connections }} 连接 · {{ item.allowed ? '允许' : '阻断' }} · {{ formatTime(item.time) }}</p></div><router-link to="/access" class="inline-block mt-4 text-sm text-blue-600">全部访问记录</router-link></section>
        <section class="panel-card p-6"><h2 class="font-semibold mb-4">最近阻断目标</h2><EmptyState v-if="!dashboard.recentBlocked?.length" title="暂无阻断记录" description="只显示节点实际上报的阻断。" /><div v-for="(item,index) in dashboard.recentBlocked" :key="index" class="border-b border-gray-100 py-3 text-sm"><p class="font-mono text-red-600 break-all">{{ item.domain || item.targetIp }}</p><p class="text-xs text-gray-500 mt-1">{{ item.userName || '身份未知' }} · {{ item.nodeName }} · {{ item.connections }} 连接 · {{ formatTime(item.time) }}</p></div><router-link to="/access?tab=blocked" class="inline-block mt-4 text-sm text-blue-600">全部阻断记录</router-link></section></div>
        <section class="panel-card p-6"><div class="flex justify-between"><h2 class="font-semibold mb-4">配置链路</h2><router-link to="/topology" class="text-sm text-blue-600">节点拓扑</router-link></div><EmptyState v-if="!dashboard.chains?.length" title="暂无代理链" description="配置路径不能代替实时连通性测量。" /><div v-for="chain in dashboard.chains" :key="chain.id" class="border-b border-gray-100 py-3 text-sm"><router-link :to="'/proxy/chains/'+chain.id+'/edit'" class="font-semibold text-blue-600">{{ chain.name }}</router-link><p class="mt-2">{{ chain.nodeIds.map(nodeName).join(' → ') }}</p><p class="text-xs text-gray-500 mt-1">{{ chain.enabled ? '草稿启用' : '草稿停用' }} · 保存和发布状态独立</p></div></section>
        <section class="panel-card p-6"><h2 class="font-semibold mb-4">最近配置版本结果</h2><EmptyState v-if="!dashboard.revisions?.length" title="尚无配置版本" description="创建并发布后在这里显示结果。" /><div v-for="revision in dashboard.revisions" :key="revision.id" class="flex flex-wrap justify-between gap-3 border-b border-gray-100 py-3 text-sm"><div><router-link to="/system/revisions" class="font-semibold text-blue-600">#{{ revision.id }} · {{ revision.summary }}</router-link><p class="text-xs text-gray-500 mt-1">{{ formatTime(revision.createdAt) }}</p></div><StatusBadge :status="revision.status" /></div></section>
      </template>
      <p class="text-xs text-gray-500">在线节点表示控制通道心跳有效，不能证明所有出口可用。未接入的实时用户、设备和连接测量保持未知；不显示示例流量或推测延迟。</p>
    </template>
  </div>
</template>
<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted } from 'vue'; import { dashboardAPI, type Dashboard, type Hour } from '../api'; import { isOwner, formatTime } from '../../../app/auth'; import PageHeader from '../../../components/PageHeader.vue'; import StatusBadge from '../../../components/StatusBadge.vue'; import TrafficValue from '../../../components/TrafficValue.vue'; import EmptyState from '../../../components/EmptyState.vue'; import LoadingSkeleton from '../../../components/LoadingSkeleton.vue'; import ErrorState from '../../../components/ErrorState.vue';
const dashboard=ref<Dashboard|null>(null);const loading=ref(false);const error=ref('');let timer:ReturnType<typeof setTimeout>|null=null;
const maxTraffic=computed(()=>Math.max(1,...(dashboard.value?.trend || []).map(hour=>hour.upload+hour.download)));
function barWidth(hour:Hour){return ((hour.upload+hour.download)/maxTraffic.value*100).toFixed(2)+'%';}
function nodeName(id:string){return dashboard.value?.nodeNames?.[id] || dashboard.value?.nodes.find(node=>node.id===id)?.name || id;}
async function load(){if(loading.value)return;loading.value=true;try{dashboard.value=await dashboardAPI.get();error.value='';}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
function schedule(){if(timer)return;timer=setTimeout(()=>{timer=null;load();},300);}
onMounted(()=>{load();for(const event of ['proxy-node-status','proxy-deployment-status','proxy-dashboard-status','proxy-system-settings'])window.addEventListener(event,schedule);});onUnmounted(()=>{if(timer)clearTimeout(timer);for(const event of ['proxy-node-status','proxy-deployment-status','proxy-dashboard-status','proxy-system-settings'])window.removeEventListener(event,schedule);});
</script>


